// On-device anomaly classifier: a shallow decision tree over the 15 quantised
// baseline-relative z-scores. The tree lives in flash (model_weights.h,
// generated by ml/train.py) and is walked with int8 comparisons only.
#pragma once

#include <stdint.h>

#include "model_types.h"

struct Prediction {
  uint8_t label;      // 0 = within personal baseline, 1 = possible irregularity
  uint8_t pAnomaly;   // share of anomalous training windows in the leaf, %
  uint8_t leaf;       // leaf node index (for logging / debugging)
};

namespace classifier {

// Classifies one window with the generated model.
Prediction predict(const int8_t* z);

// Walks an arbitrary tree stored in PROGMEM (used by tests).
Prediction predictWith(const ModelNode* nodesP, uint8_t numNodes, const int8_t* z);

// PROGMEM pointer to the per-feature baseline scale floors of the model.
const int32_t* scaleFloors();

}  // namespace classifier
